use vstd::prelude::*;

verus! {
    /// remove_element: given a vector `s` of i32 and an index `k` with k < s.len(),
    /// returns a new vector `v` with the element at index `k` removed.
    /// 
    /// Ensures:
    /// 1. v.len() == s.len() - 1
    /// 2. ∀ i < k. v[i] == s[i]
    /// 3. ∀ k ≤ i < v.len(). v[i] == s[i+1]
    fn remove_element(s: &Vec<i32>, k: usize) -> (v: Vec<i32>)
        requires
            k < s.len(),
        ensures
            v.len() == s.len() - 1,
            forall |i: usize| i < k ==> v[i] == s[i],
            forall |i: usize| k <= i && i < v.len() ==> v[i] == s[i + 1],
    {
        let mut v: Vec<i32> = Vec::new();

        //
        // First loop: copy elements 0..k
        //
        let mut i: usize = 0;
        while i < k
            invariant
                i <= k,
                v.len() == i,
                forall |j: usize| j < i ==> v[j] == s[j],
            decreases k - i,
        {
            v.push(s[i]);
            i += 1;
        }

        //
        // Second loop: copy elements k+1..s.len()
        //
        let mut j: usize = k + 1;
        while j < s.len()
            invariant
                // j runs from k+1 up to s.len()
                k + 1 <= j && j <= s.len(),
                // so far we've pushed exactly j-1 elements
                v.len() == j - 1,
                // the prefix up to k was preserved
                forall |t: usize| t < k ==> v[t] == s[t],
                // the suffix after k is shifted by one
                forall |t: usize| k <= t && t < v.len() ==> v[t] == s[t + 1],
            decreases s.len() - j,
        {
            v.push(s[j]);
            j += 1;
        }

        v
    }
}

